        if(searchPlaceholder is not null)searchPlaceholder.Visibility=search.Text.Length==0?Visibility.Visible:Visibility.Collapsed;
        if(clearSearch is not null)clearSearch.Visibility=search.Text.Length==0?Visibility.Collapsed:Visibility.Visible;
        searchStatus.Text=q.Length==0?"仅搜索本页设置，不搜索行程。":count==0?"未找到相关设置，试试“主题”“字号”或“API”。":$"找到 {count} 组相关设置";
